import type OpenAI from 'openai';
import { forEachSequential } from '../common/async-sequence';
import type { StructuredLogger } from '../logging/structured-logger';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import { executeToolAction, type ExecuteToolActionDeps } from './unified-agent-tool-router.helpers';
import { isAllowedTool, parseToolArgs } from './unified-agent-tool-parser.helpers';
import type { ActionEntry } from './unified-agent.types';

type UnknownRecord = Record<string, unknown>;

export async function processUnifiedAgentToolCalls(params: {
  actions: UnifiedAgentActionsService;
  assistantMessage: OpenAI.Chat.ChatCompletionMessage;
  contactId: string;
  executeTools: boolean;
  logger: StructuredLogger;
  phone: string;
  toolRouterDeps: ExecuteToolActionDeps;
  workspaceId: string;
  allowedTools?: string[];
  context?: UnknownRecord;
}): Promise<ActionEntry[]> {
  const actionsList: ActionEntry[] = [];
  if (!params.executeTools || !params.assistantMessage.tool_calls?.length) {
    return actionsList;
  }

  await forEachSequential(params.assistantMessage.tool_calls, async (toolCall) => {
    if (toolCall.type !== 'function') {
      return;
    }
    const toolName = toolCall.function.name;
    if (!isAllowedTool(toolName, params.allowedTools)) {
      params.logger.warn(
        `Blocked disallowed agent tool call: workspaceId=${params.workspaceId} tool=${toolName}`,
      );
      const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
      actionsList.push({ tool: toolName, args: {}, result: blockedResult });
      await params.actions.logAutopilotEvent(
        params.workspaceId,
        params.contactId,
        toolName,
        {},
        blockedResult,
      );
      return;
    }
    const toolArgs = parseToolArgs(params.logger, toolName, toolCall.function.arguments);
    const result = await executeToolAction(
      params.toolRouterDeps,
      params.workspaceId,
      params.contactId,
      params.phone,
      toolName,
      toolArgs,
      params.context,
    );
    actionsList.push({ tool: toolName, args: toolArgs, result });
    await params.actions.logAutopilotEvent(
      params.workspaceId,
      params.contactId,
      toolName,
      toolArgs,
      result,
    );
  });

  return actionsList;
}
